mapper.insert:
INSERT INTO user_mypage (mypage_user_id, user_mypage_contents)
VALUES (#{myPageUserId}, #{userMyPageContents})
ON DUPLICATE KEY UPDATE user_mypage_contents = #{userMyPageContents};

mapper.select:
select  mypage_user, user_mypage_contents, mypage_user_id
from user_mypage
where mypage_user_id = #{memberId}
order by user_mypage_idx desc;

select  mypage_user, user_mypage_contents
from user_mypage
where mypage_user = #{myPageUser}
order by user_mypage_idx desc;
